import { CSSProperties, ReactElement } from 'react';
import { ColorPalette } from '../../core/types/color-palette.js';
import { ColoredRange } from '../../core/types/colored-range.js';
/** The Honeycomb chart ref */
export interface HoneycombChartRef {
    /** The honeycomb chart root element */
    readonly element: HTMLDivElement | null;
    /** Downloads honeycomb chart raw data .*/
    downloadData: () => void;
    /** Returns the current serialized config of the HoneycombChart.*/
    getConfig: () => string;
}
/** Available tile shapes for the honeycomb */
export type HoneycombTileShape = 'circle' | 'square' | 'hexagon';
/** Information hold by each tile in the honeycomb */
export type HoneycombTileData = HoneycombTileNumericData | HoneycombTileCategoricalData;
export type HoneycombTileNumericData = {
    name?: string;
    value: number;
};
export type HoneycombTileCategoricalData = {
    name?: string;
    value: string;
};
export interface HoneycombBaseProps {
    /**
     * The shape of the honeycomb tiles.
     * @defaultValue 'hexagon'
     */
    shape?: HoneycombTileShape;
    /**
     * The width of the chart. If a number is passed, it will be treated as px.
     * @defaultValue 100%
     */
    width?: number;
    /**
     * The height of the chart. If a number is passed, it will be treated as px.
     * @defaultValue 150
     */
    height?: number;
    /** Show the loading indicator when set to true.
     * @defaultValue false
     */
    loading?: boolean;
    /** Callback to display series actions for a tile */
    seriesActions?: (tile: HoneycombTileData) => ReactElement;
    /** Class names to be attached to the outer container. */
    className?: string;
    /** Inline styles that will override the outer container. */
    style?: CSSProperties;
}
/**
 * HoneycombCharts props when using a categorical dataset
 */
export interface HoneycombCategoricalProps extends HoneycombBaseProps {
    /** Honeycomb categorical data */
    data: string | string[] | HoneycombTileCategoricalData[];
    /** Color Scheme to be applied to the categorical data */
    colorScheme?: ColorPalette | {
        [key: string]: string;
    };
}
/**
 * HoneycombCharts props when using a numeric dataset
 */
export interface HoneycombChartNumericalProps extends HoneycombBaseProps {
    /** Honeycomb numerical data */
    data: number | number[] | HoneycombTileNumericData[];
    /** Color Scheme to be applied to the numerical data */
    colorScheme?: ColorPalette | ColoredRange[];
}
/** The Honeycomb component props */
export type HoneycombChartProps = HoneycombCategoricalProps | HoneycombChartNumericalProps;
